package cn.hydrogen.launcher;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import org.json.*;import java.lang.reflect.*;import java.util.*;import java.io.*;
/** Real paired QQ replies only. Diagnostic oracle is explicitly separated from production assertions. */
final class QqReentryFlow {
 final Instrumentation test;final boolean diagnose;MainActivity home;QqMusicBridge bridge;int passed,failed;final StringBuilder report=new StringBuilder("Real QQ repeated-entry controls; no synthetic replies\n");final List<String> events=Collections.synchronizedList(new ArrayList<>());volatile long eventAt;volatile int eventState=-1;volatile String eventTitle="";volatile long eventPosition=-1;
 QqReentryFlow(Instrumentation t,boolean d){test=t;diagnose=d;}
 interface Condition{boolean value()throws Exception;}
 void main(Runnable r){test.runOnMainSync(r);}
 boolean await(Condition c,int seconds)throws Exception{long end=SystemClock.elapsedRealtime()+seconds*1000;do{if(c.value())return true;Thread.sleep(100);}while(SystemClock.elapsedRealtime()<end);return c.value();}
 void check(boolean value,String label){if(value)passed++;else failed++;report.append(value?"PASS ":"FAIL ").append(label).append(" state=").append(eventState).append(" title=").append(eventTitle).append('\n');}
 Object field(Object o,String name)throws Exception{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(o);}
 View desc(View view,String name){if(name.contentEquals(view.getContentDescription()==null?"":view.getContentDescription()))return view;if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int i=0;i<group.getChildCount();i++){View got=desc(group.getChildAt(i),name);if(got!=null&&got.isShown())return got;}}return null;}
 void focus()throws Exception{if(!await(()->home.hasWindowFocus(),15))throw new AssertionError("desktop focus did not return");main(()->home.showPage(MainActivity.CARDS));Thread.sleep(400);}
 void identify()throws Exception{bridge=(QqMusicBridge)field(home,"musicBridge");main(bridge::subscribe);if(!await(()->bridge.connected&&bridge.trackConfirmed&&!bridge.title.isEmpty(),25))throw new AssertionError("no actual QQ song snapshot");}
 Intent oracle(int command){int index=command==0?5:command==1?4:command==2?12:13;return new Intent(QqMusicBridge.WEDRIVE_ACTION).setComponent(new ComponentName(Config.MUSIC,"com.tencent.qqmusiccar.app.reciver.BroadcastReceiverCenterForWeDrive")).putExtra(QqMusicBridge.WEDRIVE_EXTRA,"{\"command\":{\"extData\":{\"index\":"+index+"}}}");}
 void action(int command,String stage)throws Exception{
  if(command>=2&&!await(()->bridge.state==2||bridge.state==3,15))throw new AssertionError("native track still loading before explicit skip");
  if(command>=2)Thread.sleep(500);
  String before=bridge.title;long at=SystemClock.elapsedRealtime();int desired=command==0?2:3;
  if(diagnose)main(()->bridge.command(command));else {String label=command==0||command==1?"播放 / 暂停":command==2?"上一首":"下一首";int[] xy=new int[2];main(()->{View button=desc(home.getWindow().getDecorView(),label);if(button==null)throw new AssertionError("missing "+label);button.getLocationOnScreen(xy);xy[0]+=button.getWidth()/2;xy[1]+=button.getHeight()/2;});long down=SystemClock.uptimeMillis();android.view.MotionEvent press=android.view.MotionEvent.obtain(down,down,0,xy[0],xy[1],0),release=android.view.MotionEvent.obtain(down,down+70,1,xy[0],xy[1],0);try{test.sendPointerSync(press);test.sendPointerSync(release);}finally{press.recycle();release.recycle();}}
  boolean ok=await(()->command<=1?eventAt>=at&&eventState==desired:!bridge.title.equals(before)&&eventTitle.equals(bridge.title),12);
  check(ok,stage+" production command "+command);
  if(command==0&&ok){long pos=bridge.currentPosition();Thread.sleep(1800);check(bridge.currentPosition()>pos+500,stage+" actual playback advances");}
  if(command==1&&ok){Thread.sleep(2500);long pos=bridge.currentPosition();Thread.sleep(800);check(bridge.state==3&&eventState==3&&Math.abs(bridge.currentPosition()-eventPosition)<250&&Math.abs(bridge.currentPosition()-pos)<350,stage+" pause settles at actual native position");}
  if(!ok&&diagnose){long recovery=SystemClock.elapsedRealtime();main(()->test.getTargetContext().sendBroadcast(oracle(command)));boolean direct=await(()->command<=1?eventAt>=recovery&&eventState==desired:!bridge.title.equals(before),12);report.append("DIAGNOSTIC direct native index command ").append(command).append(direct?" succeeded":" failed").append('\n');}
 }
 @android.annotation.SuppressLint("UnspecifiedRegisterReceiverFlag")
 void run(){Context app=test.getTargetContext();BroadcastReceiver receiver=new BroadcastReceiver(){public void onReceive(Context c,Intent intent){try{JSONObject root=new JSONObject(intent.getStringExtra(QqMusicBridge.EXTRA));JSONObject cmd=root.optJSONObject("command"),data=cmd==null?null:cmd.optJSONObject("data");if(cmd==null||data==null)return;String method=cmd.optString("method");long now=SystemClock.elapsedRealtime();if("update_state".equals(method)){eventAt=now;eventState=data.optInt("state",-1);eventPosition=data.optLong("curr_time",-1);}if(data.has("key_title")&&!data.optString("key_title").isEmpty())eventTitle=data.optString("key_title");if(events.size()<1200)events.add(now+" "+method+" state="+data.optInt("state",-1)+" pos="+data.optLong("curr_time",-1)+" title="+data.optString("key_title"));}catch(Exception e){events.add(e.toString());}}};boolean registered=false;
  try{main(()->{if(Build.VERSION.SDK_INT>=33)app.registerReceiver(receiver,new IntentFilter(QqMusicBridge.EVENTS),Context.RECEIVER_EXPORTED);else app.registerReceiver(receiver,new IntentFilter(QqMusicBridge.EVENTS));});registered=true;
   home=(MainActivity)test.startActivitySync(new Intent(app,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));focus();identify();report.append("Initial actual snapshot: ").append(bridge.title).append(" state=").append(bridge.state).append('\n');
   if(diagnose){main(()->app.sendBroadcast(oracle(0)));await(()->eventState==2,15);report.append("DIAGNOSTIC setup uses one direct native play to make pause observable\n");}
   main(()->Ui.launch(home,Config.MUSIC));await(()->!home.hasWindowFocus(),12);Thread.sleep(1000);main(()->app.startActivity(new Intent(app,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_REORDER_TO_FRONT)));focus();identify();
   action(bridge.state==2?1:0,"after native QQ return");action(bridge.state==2?1:0,"after native QQ return toggle");action(3,"after native QQ return next");action(2,"after native QQ return previous");
   if(!diagnose){QqMusicBridge old=bridge;MainActivity former=home;main(former::finish);Thread.sleep(500);home=(MainActivity)test.startActivitySync(new Intent(app,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));focus();identify();check(home!=former&&!((Boolean)field(bridge,"closed")),"new desktop has a live music bridge (existing floating lease may share it)");action(bridge.state==2?1:0,"second desktop entry");action(bridge.state==2?1:0,"second desktop entry toggle");action(3,"second desktop entry next");action(2,"second desktop entry previous");}
  }catch(Throwable error){failed++;report.append("FAIL ").append(error).append('\n');}finally{if(registered)main(()->app.unregisterReceiver(receiver));}
  report.append("Real events\n");synchronized(events){for(String event:events)report.append(event).append('\n');}report.append("QQ_REENTRY_RESULT passed=").append(passed).append(" failed=").append(failed).append('\n');try(Writer out=new OutputStreamWriter(new FileOutputStream(new File(app.getFilesDir(),"qq-reentry-report.txt")),"UTF-8")){out.write(report.toString());}catch(Exception ignored){}Bundle result=new Bundle();result.putString("stream",report.toString());test.finish(failed==0?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);
 }
}
